# ── Trampoline pattern ──────────────────────────────────────────────────────

def trampoline(fn: Callable) -> Callable:
    @functools.wraps(fn)
    def wrapped(*args, **kwargs):
        while True:
            try:
                res = fn(*args, **kwargs)
            except StopIteration as e:
                return e.value
            else:
                args = ()
                kwargs.clear()
                if isinstance(res, tuple):
                    fn, args, kwargs = res
                elif isinstance(res, list):
                    fn, *res = res
                    args += res
                elif callable(res):
                    fn = res
            finally:
                pass
    return wrapped


